import {topics,example,glossary,officialSources,CREDIT} from './data/content.js';
import {api} from './api.js';
import {simulations,simulationView} from './simulations.js';
import {papers} from './data/papers.js';
import {videos} from './data/videos.js?v=20261001-library60';
import {videoLibrary,mountVideoLibraries} from './video-library.js?v=20261001-library60b';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const parse=(s,f)=>{try{return JSON.parse(s)||f}catch{return f}};
const state={records:parse(localStorage.getItem('qj-guest-records'),[]),preferences:parse(localStorage.getItem('qj-preferences'),{}),profile:null,educator:false,resources:[],newtonMode:null,flash:0,flashFlipped:false,timer:{remaining:1500,run:false,end:null,kind:'Focus'},chatBusy:false};
let route=[],activeExample=null,revealed=0,toastTimeout,renderId=0;
const main=$('#main');
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function modal(html){$('#modal-content').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function close(){$('#modal').close()}
function current(kind,key){return state.records.find(r=>r.kind===kind&&r.record_key===key)?.data}
function records(kind){return state.records.filter(r=>r.kind===kind)}
async function save(kind,key,data){if(api.session)await api.save(kind,key,data);state.records=state.records.filter(r=>!(r.kind===kind&&r.record_key===key));state.records.push({kind,record_key:key,data,updated_at:new Date().toISOString()});if(!api.session)localStorage.setItem('qj-guest-records',JSON.stringify(state.records));}
async function remove(kind,key){if(api.session)await api.remove(kind,key);state.records=state.records.filter(r=>!(r.kind===kind&&r.record_key===key));if(!api.session)localStorage.setItem('qj-guest-records',JSON.stringify(state.records));}
function download(name,text,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function applyPreferences(){const p=state.preferences;document.body.classList.toggle('dark',p.dark||false);document.body.classList.toggle('contrast',p.contrast||false);document.body.classList.toggle('quiet',p.quiet||false);document.body.classList.toggle('reduced-motion',p.motion||false);document.body.classList.toggle('reading',p.reading||false);document.body.classList.toggle('focus-mode',p.focus||false);document.documentElement.style.setProperty('--font-scale',p.size||1);document.documentElement.style.setProperty('--leading',p.spacing||1.65);const theme=$('[data-action="theme"]');if(theme){theme.innerHTML=p.dark?'☀ <span>Light mode</span>':'☾ <span>Dark mode</span>';theme.setAttribute('aria-label',p.dark?'Switch to light mode':'Switch to dark mode');}localStorage.setItem('qj-preferences',JSON.stringify(p));}
function accountUI(){const u=api.session?.user,name=state.profile?.display_name||u?.user_metadata?.display_name||'Curious mind';$('#auth-button').textContent=u?'My account':'Log in / Sign up';$('#account-chip').innerHTML=`<span class="avatar">${esc(u?name[0].toUpperCase():'↗')}</span><div><strong>${esc(u?name:'Just exploring?')}</strong><br><small>${u?'Account connected':'Guest · saved on this device'}</small></div>`;}
async function hydrate(){if(!api.session){state.educator=false;accountUI();return}try{const u=await api.user();const [r,p,e]=await Promise.all([api.records(),api.getProfile(),api.educator()]);state.records=r;state.profile=p[0]||{display_name:u.user_metadata?.display_name||'Learner',preferences:{}};state.educator=e.length>0;if(p[0]?.preferences){state.preferences={...state.preferences,...p[0].preferences};applyPreferences()}accountUI();}catch(e){toast(e.message);accountUI();}}
const title=(eyebrow,heading,desc,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eyebrow}</div><h1>${heading}</h1><p>${desc}</p></div>${actions?`<div class="actions">${actions}</div>`:''}</div>`;
const credit=()=>`<div class="credit">${CREDIT} · Practice resources · <a href="#about">About this material</a></div>`;
const btn=(action,text,cls='secondary',data='')=>`<button class="button ${cls}" data-action="${action}" ${data}>${text}</button>`;
function paperTabs(active,base='learn'){return`<div class="tabs"><a class="${active===1?'active':''}" href="#${base}/1">Paper 1 · Physics</a><a class="${active===2?'active':''}" href="#${base}/2">Paper 2 · Chemistry</a></div>`}


function topicVideos(topic){return videoLibrary({topic});}
function paperVideos(p){return videoLibrary({paper:p,kind:'past-paper'});}
function topicCard(t){const completed=!!current('progress',t.id)?.complete;return`<a class="topic-card" href="#topic/${t.id}" data-paper="${t.paper}"><span class="topic-icon">${t.icon}</span><h3>${esc(t.title)}</h3><p>${esc(t.prerequisite)}</p><div class="bottom-line"><span>100 questions · ${videos.filter(v=>v.topic===t.id).length} videos</span><span>${completed?'✓ Reviewed':'Explore ↗'}</span></div></a>`;}
const orbit=`<svg viewBox="0 0 400 320" aria-label="An illustrated atom with orbiting dots" role="img"><circle cx="200" cy="155" r="120" fill="#eee9df"/><path d="M95 250H320M100 55V267" stroke="#d0d3c8" stroke-width="1" stroke-dasharray="4 5"/><ellipse cx="210" cy="155" rx="139" ry="48" transform="rotate(-35 210 155)" fill="none" stroke="#263b31" stroke-width="1.6"/><ellipse cx="210" cy="155" rx="139" ry="48" transform="rotate(35 210 155)" fill="none" stroke="#263b31" stroke-width="1.6"/><ellipse cx="210" cy="155" rx="122" ry="50" transform="rotate(90 210 155)" fill="none" stroke="#263b31" stroke-width="1.6"/><circle cx="210" cy="155" r="32" fill="#e98251"/><circle cx="210" cy="155" r="13" fill="#fbebd9"/><circle cx="305" cy="89" r="13" fill="#baa6d7" stroke="#263b31" stroke-width="1.5"/><circle cx="99" cy="106" r="8" fill="#e98251" stroke="#263b31" stroke-width="1.5"/><circle cx="231" cy="272" r="10" fill="#acc39b" stroke="#263b31" stroke-width="1.5"/><path d="M328 205v22m-11-11h22M70 195v15m-7-7h14" stroke="#c35227" stroke-width="2"/><text x="310" y="55" fill="#6b7669" font-size="15" font-family="monospace">E = hf</text></svg>`;
function home(){const done=records('progress').filter(r=>r.data.complete).length,attempts=records('attempt').length;return`<section class="hero"><div><div class="eyebrow">GRADE 12 PHYSICAL SCIENCES · CAPS</div><h1>A little curiosity.<br>A <em>quantum jump.</em></h1><p>Big concepts, smaller steps. Find your way through Physics and Chemistry, with a little help from Newton.</p><div class="actions"><a class="button" href="#learn/1">Let’s get into it <span>↗</span></a><a class="quiet-button" href="#lab">Or, try an experiment →</a></div></div><div class="hero-art"><span class="art-tag">confusion → curiosity → clarity</span>${orbit}<span class="art-tag bottom">one small step counts.</span><span class="hero-caption">A SPACE FOR YOUR NEXT AHA.</span></div></section><section class="overview-grid"><a class="paper-card physics" href="#learn/1"><span class="mini-label">PAPER 01</span><span class="corner-art">↗</span><h2>Physics</h2><p>From things that move to the little things that make light.</p><span class="card-link">11 sections · 1,100 questions <b>↗</b></span></a><a class="paper-card chemistry" href="#learn/2"><span class="mini-label">PAPER 02</span><span class="corner-art">⬡</span><h2>Chemistry</h2><p>A little structure. A little reaction. A whole lot of understanding.</p><span class="card-link">9 sections · 900 questions <b>↗</b></span></a><div class="daily-card"><span class="pill">✦ A SMALL WIN FOR TODAY</span><h3>Just one thing.</h3><p>${attempts?`${attempts} practice attempts saved. ${done} topics reviewed. Ready for your next little leap?`:'Pick a topic. Try one question. That’s a perfectly good place to begin.'}</p><a class="button secondary small" href="#practice/forces/0">Take a 5-minute leap →</a></div></section><div class="section-heading"><div><h2>Find your “oh, I get it.”</h2><p>Start with a concept you’d like to make friends with.</p></div><a href="#learn/1" class="link-button">All topics ↗</a></div><section class="topic-grid">${[topics[0],topics[3],topics[7],topics[10],topics[15],topics[16]].map(topicCard).join('')}</section><section class="newton-strip"><div class="newton-face">⌐◉_◉</div><div><h3>Meet Newton. Big on the “why”.</h3><p>A patient study companion for the bit that hasn’t clicked yet.</p></div><a class="button secondary" href="#newton">Ask Newton ↗</a></section>`;}
function learn(){const p=Number(route[1])===2?2:1;return title(`PAPER ${p}`,p===1?'Make sense of motion.':'Find the chemistry.',p===1?'Build your Physics understanding, one relationship at a time.':'Connect the particles, patterns and reactions behind Paper 2.')+paperTabs(p)+`<div class="toolbar"><input id="topic-search" type="search" placeholder="Find a topic or concept…" aria-label="Search topics"></div><div class="topic-grid" id="topic-list">${topics.filter(t=>t.paper===p).map(topicCard).join('')}</div><div class="caption" style="margin-top:22px">Each section has 100 structured practice questions, including numerical variations. These support revision; use official papers for full exam-level application.</div>`;}
function videosPage(){const t=topics.find(t=>t.id===route[1]);if(t)return topicNavigation(t)+title('VIDEO LESSONS',esc(t.title),'Choose a lesson, then pause and practise.',`<a class="button secondary" href="#topic/${t.id}">Topic notes & practice</a>`)+topicVideos(t.id);return title('VIDEO LIBRARY','Find the explanation that clicks.','Choose a topic to browse its lessons, examples and revision.')+`<div class="toolbar"><input id="video-topic-search" type="search" placeholder="Find a topic…" aria-label="Find a video topic"></div><div id="video-topic-list">${[1,2].map(p=>`<h2 class="video-paper-heading">Paper ${p} · ${p===1?'Physics':'Chemistry'}</h2><div class="topic-grid">${topics.filter(t=>t.paper===p).map(t=>`<a class="topic-card" href="#videos/${t.id}"><span class="topic-icon">${t.icon}</span><h3>${esc(t.title)}</h3><span class="pill">${videos.filter(v=>v.topic===t.id).length} videos</span></a>`).join('')}</div>`).join('')}</div>`;}
function topicNavigation(t){const group=topics.filter(x=>x.paper===t.paper),i=group.indexOf(t);return `<nav class="topic-navigation" aria-label="Topic navigation"><a href="#learn/${t.paper}">All ${t.paper===1?'Physics':'Chemistry'} topics</a><label>Change topic<select id="topic-jump">${[1,2].map(p=>`<optgroup label="Paper ${p} · ${p===1?'Physics':'Chemistry'}">${topics.filter(x=>x.paper===p).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${esc(x.title)}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="actions">${i>0?`<a href="#${route[0]==='videos'?'videos':'topic'}/${group[i-1].id}" aria-label="Previous topic: ${esc(group[i-1].title)}">Previous topic</a>`:''}${i<group.length-1?`<a href="#${route[0]==='videos'?'videos':'topic'}/${group[i+1].id}" aria-label="Next topic: ${esc(group[i+1].title)}">Next topic</a>`:''}</div></nav>`;}
function topicPage(){const t=topics.find(t=>t.id===route[1])||topics[0];return topicNavigation(t)+title(`PAPER ${t.paper} · LEARN`,esc(t.title),'A clear idea first. The calculations come next.',`<a class="button" href="#practice/${t.id}/0">Try a worked example ↗</a>`)+`<div class="topic-shortcuts"><button class="button secondary small" data-action="topic-videos">Watch video lessons</button><a class="button secondary small" href="#practice/${t.id}/0">Practise questions</a><a class="button secondary small" href="#papers/${t.paper}">Past papers</a><a class="button secondary small" href="#newton/${t.id}">Ask Newton</a></div><div class="two-cols"><section><div class="panel"><div class="topic-icon">${t.icon}</div><h2>The idea, without the fog.</h2><p>${esc(t.summary)}</p><div class="formula">${esc(t.formula)}</div><div class="callout"><strong>Watch out</strong><br>${esc(t.trap)}</div><h3>A little exam wisdom</h3><p>${esc(t.tip)}</p>${credit()}</div><div class="panel"><h3>Your own “aha” notes</h3><label for="topic-note">What made this click for you?</label><textarea id="topic-note" placeholder="Write it in your own words…">${esc(current('note',t.id)?.text||'')}</textarea><div class="actions" style="margin-top:12px">${btn('save-note','Save note','','data-topic="'+t.id+'"')}${btn('speak','Read lesson aloud','secondary','data-text="'+esc(t.summary)+'"')}${btn('stop-speech','Stop reading','ghost')}</div></div></section><aside><div class="panel"><h3>Your next small steps</h3><div class="detail-row"><strong>Before this topic</strong>${esc(t.prerequisite)}</div><div class="detail-row"><strong>Practice bank</strong>100 questions with structured solutions.</div><div class="detail-row"><strong>Units to notice</strong>${esc(t.unit)}</div><div class="actions" style="margin-top:20px">${btn('complete',current('progress',t.id)?.complete?'✓ Reviewed · undo':'Mark topic reviewed','secondary',`data-topic="${t.id}"`)}<a class="button secondary" href="#newton/${t.id}">Ask Newton</a><a class="button secondary" href="#lab/${simulations.find(s=>s.topic===t.id)?.id||'forces'}">Explore the lab ↗</a>${btn('print','Print summary','ghost')}</div></div><div class="panel lilac"><h3>You’re allowed to go slowly.</h3><p>Try one question with the steps open. Then try another without looking.</p><a href="#practice/${t.id}/4" class="link-button">Start small ↗</a></div></aside></div>${topicVideos(t.id)}`;}
function practice(){const t=topics.find(t=>t.id===route[1])||topics[0],i=Math.max(0,Math.min(99,Number(route[2])||0));activeExample=example(t.id,i);revealed=0;const e=activeExample;return title(`PAPER ${t.paper} · WORKED PRACTICE`,esc(t.title),'Read the question. Decide what you know. Take it one step at a time.',`<a class="button secondary" href="#topic/${t.id}">← Lesson</a>`)+`<div class="two-cols"><section class="panel"><div class="example-top"><span class="pill peach">QUESTION ${i+1} OF 100</span><span class="pill">${e.difficulty}</span></div><div class="question">${esc(e.question)}</div><div class="callout"><strong>Known information</strong><br>${esc(e.known)}<br><strong>Find:</strong> ${esc(e.find)}</div>${e.number!==null?`<form id="answer-form" class="answer-box"><input name="answer" aria-label="Your numerical answer" placeholder="Try an answer, e.g. 2.5e-3" required inputmode="text"><span class="caption">${esc(e.unit)}</span><button class="button" type="submit">Check</button></form><div id="answer-feedback" class="feedback" role="status"></div>`:`<label>Try explaining it yourself<textarea id="written-answer" placeholder="Your reasoning…"></textarea></label>${btn('self-attempt','Save my attempt','secondary')}`}<div class="actions" style="margin-top:20px">${btn('next-step','Show the first step','','id="step-button"')}${btn('all-steps','Show full solution','secondary')}${btn('bookmark',current('bookmark',e.id)?'♥ Saved':'♡ Save question','ghost',`id="bookmark-button"`)}</div><div id="solution"></div><div id="solution-note"></div><div class="actions" style="margin-top:24px"><a class="button secondary ${i===0?'disabled':''}" href="#practice/${t.id}/${Math.max(0,i-1)}">← Previous</a><a class="button" href="#practice/${t.id}/${(i+1)%100}">Next question →</a>${btn('random-example','Surprise me','ghost',`data-topic="${t.id}"`)}</div>${credit()}</section><aside><div class="panel"><h3>Choose your next question</h3><p class="caption">Questions include different tasks and numerical variations. Mix practice with official past papers.</p><div class="numbers">${Array.from({length:100},(_,j)=>`<button class="${j===i?'active':''}" data-action="question" data-topic="${t.id}" data-index="${j}" aria-label="Question ${j+1}">${j+1}</button>`).join('')}</div></div><div class="panel"><h3>Need a different explanation?</h3><p class="caption">Bring this question to Newton, or revisit the idea behind it.</p><a class="button secondary" href="#newton/${t.id}">Ask Newton ↗</a><div class="actions" style="margin-top:12px">${btn('speak','Read question','ghost',`data-text="${esc(e.question)}"`)}${btn('stop-speech','Stop reading','ghost')}${btn('print-example','Print solution','ghost')}</div></div></aside></div>`;}
function solution(){if(!activeExample)return;$('#solution').innerHTML=activeExample.steps.slice(0,revealed).map((s,i)=>`<div class="example-step"><span class="step-number">${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.text)}</p></div></div>`).join('');$('#step-button').textContent=revealed>=5?'All steps revealed':`Show step ${revealed+1}`;$('#step-button').disabled=revealed>=5;if(revealed>=5)$('#solution-note').innerHTML=`<div class="callout"><strong>Common mistake</strong><br>${esc(activeExample.trap)}</div><p class="caption"><strong>Exam tip:</strong> ${esc(activeExample.tip)}</p>`;}
function paperPage(){const p=Number(route[1])===2?2:1;return title('THE PAST PAPER SHELF','Meet the exam on your terms.','Official question papers and matching marking guidelines. Keep your practice purposeful, not panicky.')+paperTabs(p,'papers')+`<div class="toolbar"><select id="paper-year" aria-label="Filter by year"><option value="all">All years</option>${[...new Set(papers.map(p=>p.year))].sort((a,b)=>b-a).map(y=>`<option>${y}</option>`).join('')}</select><select id="paper-language" aria-label="Filter paper language"><option>English</option></select><a class="button secondary" href="#planner">Set a practice timer</a></div><div id="paper-list">${paperRows(p)}</div><div class="panel"><h3>Study the memo after you try.</h3><p class="caption">Keep the question paper and memo in separate tabs. Work through the question first, then compare your reasoning and units. Official files remain credited to the Department of Basic Education. Some links open Hlayiso, which limits guest downloads and offers free registration. Memos are bilingual English / Afrikaans.</p><a class="link-button" href="${officialSources[1].url}" target="_blank" rel="noopener">Browse the complete DBE archive ↗</a></div>${paperVideos(p)}<div class="section-heading"><h2>Find practice by section</h2></div><div class="topic-grid">${topics.filter(t=>t.paper===p).map(topicCard).join('')}</div>`;}
function paperRows(p){const y=$('#paper-year')?.value||'all',lang=$('#paper-language')?.value||'English';const list=papers.filter(x=>x.paper===p&&(y==='all'||x.year===Number(y))).sort((a,b)=>b.year-a.year);return list.map(x=>`<article class="paper-row"><div class="paper-year">${x.year}</div><div><h3>Paper ${x.paper} · ${x.paper===1?'Physics':'Chemistry'}</h3><p>${esc(x.sitting||'November')} · ${esc(x.province||'National')} · ${lang} · ${esc(x.host||'DBE')}</p><p>Curated by Simoné Govender</p></div><div class="actions"><a class="button secondary" href="${esc(x.question)}" target="_blank" rel="noopener">Question paper ↗</a>${x.memo?`<a class="button" href="${esc(x.memo)}" target="_blank" rel="noopener">Memo ↗</a>`:''}</div></article>`).join('')||'<div class="empty">No verified papers match this filter.</div>';}
function lab(){const s=simulations.find(s=>s.id===route[1])||simulations[0];return title('THE EXPERIMENT LAB','Make the invisible click.','Move a slider. Make a prediction. Watch the relationship change.')+`<div class="toolbar"><select id="simulation-select" aria-label="Choose a simulation">${simulations.map(x=>`<option value="${x.id}" ${x.id===s.id?'selected':''}>${x.title}</option>`).join('')}</select><a class="button secondary" href="#topic/${s.topic}">Related lesson ↗</a></div><section class="panel"><div class="section-heading" style="margin-top:0"><div><h2>${s.title}</h2><p>${s.subtitle}</p></div><span class="pill">INTERACTIVE</span></div><div class="callout"><strong>Predict first</strong><br>${s.predict}</div><div class="sim-controls">${['a','b'].map((key,i)=>{const c=i?s.b:s.a;return`<label>${c[0]}: <output id="sim-${key}-value">${c[4]}</output> ${c[5]}<input type="range" id="sim-${key}" min="${c[1]}" max="${c[2]}" step="${c[3]}" value="${c[4]}" aria-label="${c[0]}"></label>`}).join('')}</div><div id="sim-stage" class="sim-stage"></div><div id="sim-readout" class="readout" aria-live="polite"></div><p id="sim-explanation" class="sim-description"></p><p class="caption"><strong>Model assumptions:</strong> ${s.assumption}</p><div class="actions">${btn('reset-sim','Reset experiment','secondary')}<a class="button" href="#practice/${s.topic}/0">Try the working →</a></div>${credit()}</section><details><summary>Explore a PhET simulation from the University of Colorado Boulder</summary><p class="caption">External simulations retain their original credits and may have different accessibility features. Load only when you want to use data.</p>${btn('load-phet','Load circuit simulation','secondary')}<div id="phet-embed"></div><p><a class="link-button" target="_blank" rel="noopener" href="https://phet.colorado.edu/">Visit PhET ↗</a></p></details>`;}
function updateSim(){const s=simulations.find(s=>s.id===route[1])||simulations[0],a=Number($('#sim-a').value),b=Number($('#sim-b').value),v=simulationView(s.id,a,b);$('#sim-a-value').textContent=a;$('#sim-b-value').textContent=b;$('#sim-stage').innerHTML=v.diagram;$('#sim-readout').textContent=v.readout;$('#sim-explanation').textContent=v.explanation;}
function toolkit(){return title('YOUR REVISION TOOLKIT','Less rummaging. More revising.','Formulae, flashcards, definitions and small tools, all in one place.')+`<div class="tabs"><button data-action="tool-tab" data-tab="formulae" class="active">Formula bank</button><button data-action="tool-tab" data-tab="flashcards">Flashcards</button><button data-action="tool-tab" data-tab="glossary">Definitions</button><button data-action="tool-tab" data-tab="units">Unit converter</button><button data-action="tool-tab" data-tab="checklist">Revision checklist</button></div><div id="tool-content">${formulae()}</div>`;}
function formulae(){return`<div class="toolbar"><input id="formula-search" type="search" aria-label="Search formulae" placeholder="Search a topic or formula…">${btn('print','Print formulae','secondary')}</div><div class="three-cols" id="formula-list">${topics.map(t=>`<article class="panel formula-card" style="margin:0"><span class="pill">PAPER ${t.paper}</span><h3 style="margin-top:15px">${esc(t.title)}</h3><div class="formula">${esc(t.formula)}</div><p class="caption" style="margin-top:15px">${esc(t.tip)}</p><a class="link-button" href="#topic/${t.id}">Understand it ↗</a></article>`).join('')}</div>${credit()}`;}
function flashcard(){const t=glossary[state.flash%glossary.length];return`<div class="panel"><div class="flashcard"><small>CARD ${state.flash+1} / ${glossary.length}</small><h2>${esc(t[0])}</h2>${state.flashFlipped?`<p>${esc(t[1])}</p>`:'<p class="caption">Try recalling the meaning before you turn the card.</p>'}</div><div class="actions">${btn('flip-card',state.flashFlipped?'Show prompt':'Turn it over','')}${btn('next-card','Next card →','secondary')}${btn('shuffle-card','Shuffle','ghost')}${btn('known-card','I’ve got this ✓','ghost')}</div>${credit()}</div>`;}
function unitTool(){return`<div class="panel"><h2>Small prefixes. Big differences.</h2><form id="unit-form"><div class="inline-fields"><label>Value<input name="value" type="number" step="any" value="1" required></label><label>Conversion<select name="conversion"><option value="0.001|m">Millimetres → metres</option><option value="0.01|m">Centimetres → metres</option><option value="1000|m">Kilometres → metres</option><option value="0.001|dm³">cm³ → dm³</option><option value="0.000001|C">Microcoulombs → coulombs</option><option value="0.000000001|m">Nanometres → metres</option><option value="0.2777777777777778|m·s⁻¹">km/h → m/s</option><option value="60|s">Minutes → seconds</option><option value="1000|J">Kilojoules → joules</option><option value="0.001|kg">Grams → kilograms</option></select></label></div><button class="button">Convert</button></form><div id="unit-result" class="formula" style="margin-top:20px">Choose a value and conversion.</div>${credit()}</div>`;}
function checklist(){return`<div class="panel"><h2>Your revision map</h2><p class="caption">A tick means you reviewed a topic. It does not claim exam mastery.</p>${topics.map(t=>`<div class="check-row"><input type="checkbox" id="check-${t.id}" data-check-topic="${t.id}" ${current('progress',t.id)?.complete?'checked':''}><label for="check-${t.id}">Paper ${t.paper} · ${esc(t.title)}</label><a href="#topic/${t.id}" class="link-button">Open ↗</a></div>`).join('')}</div>`;}
function planner(){const plan=current('plan','settings')||{};return title('YOUR STUDY PLAN','A plan with breathing room.','Choose what fits your energy today. Small, repeatable steps count.')+`<div class="two-cols"><section><div class="panel"><h2>My next little leaps</h2><form id="task-form" class="answer-box"><input name="task" placeholder="e.g. Try three momentum questions" aria-label="New study task" maxlength="200" required><button class="button">Add task</button></form><div id="task-list">${taskList()}</div></div><div class="panel"><h3>Plan around your exam</h3><form id="plan-form"><div class="inline-fields"><label>Exam date<input type="date" name="exam" value="${esc(plan.exam||'')}"></label><label>Weekly intention<input name="intention" maxlength="150" value="${esc(plan.intention||'')}" placeholder="Four short sessions, one paper"></label></div><button class="button secondary">Save plan</button></form>${plan.exam&&!state.preferences.hideTimers?`<p class="caption" style="margin-top:15px">${Math.max(0,Math.ceil((new Date(plan.exam+'T12:00:00')-new Date())/86400000))} days until your chosen date. Use it as information, not pressure.</p>`:''}</div><div class="panel lilac"><h3>Low-energy day?</h3><p>Read one definition. Look at one worked example. Or take the break you need and choose a fresh starting point.</p><div class="actions"><a class="button secondary" href="#toolkit">One definition</a><a class="button secondary" href="#practice/forces/0">One example</a></div></div></section><aside><div class="panel"><span class="pill">FOCUS, YOUR WAY</span><div class="timer-digits" id="timer">${timerText()}</div><div class="timer-label" id="timer-label">${state.timer.kind} session · no streaks to lose</div><div class="inline-fields" style="margin-top:20px"><label>Focus minutes<input id="focus-min" type="number" min="1" max="180" value="${plan.focus||25}"></label><label>Break minutes<input id="break-min" type="number" min="1" max="60" value="${plan.break||5}"></label></div><div class="actions">${btn('timer-start',state.timer.run?'Pause':'Start','',`id="timer-start"`)}${btn('timer-reset','Reset','secondary')}${btn('timer-break','Take a break','ghost')}</div><p class="caption" style="margin-top:18px">Pause whenever you need. This timer is for study, not a strict exam attempt.</p></div></aside></div>`;}
function taskList(){return records('task').map(r=>`<div class="task ${r.data.done?'done':''}"><input type="checkbox" aria-label="Complete ${esc(r.data.text)}" data-task="${r.record_key}" ${r.data.done?'checked':''}><span class="text">${esc(r.data.text)}</span><button data-action="delete-task" data-key="${r.record_key}" aria-label="Delete task">×</button></div>`).join('')||'<p class="caption">No tasks yet. Start with something small and specific.</p>';}
function timerText(){return state.preferences.hideTimers?'Focus':`${Math.floor(state.timer.remaining/60).toString().padStart(2,'0')}:${(state.timer.remaining%60).toString().padStart(2,'0')}`;}
function savedPage(){return title('YOUR NOTEBOOK','Keep the bits that clicked.','Your notes, saved questions and practice history.',btn('export-data','Export my data','secondary'))+`<div class="two-cols"><section><div class="panel"><h2>My notes</h2>${records('note').map(r=>`<article class="detail-row"><strong>${esc(topics.find(t=>t.id===r.record_key)?.title||r.record_key)}</strong><p style="white-space:pre-wrap">${esc(r.data.text)}</p><a class="link-button" href="#topic/${r.record_key}">Edit note ↗</a></article>`).join('')||'<p class="caption">Open a lesson and jot down what helps you understand it.</p>'}</div><div class="panel"><h2>Practice history</h2>${records('attempt').slice(-30).reverse().map(r=>`<div class="detail-row"><strong>${esc(r.data.topic)} · Question ${r.data.index+1}</strong><span>${r.data.correct===true?'✓ Numerical answer matched':r.data.correct===false?'↻ Worth another look':'Self-check response saved'}</span> · <a class="link-button" href="#practice/${r.data.topicId}/${r.data.index}">Retry</a></div>`).join('')||'<p class="caption">Your attempts will appear here after you try a question.</p>'}</div></section><aside class="panel"><h2>Saved questions</h2>${records('bookmark').map(r=>`<div class="detail-row"><a href="#practice/${r.data.topic}/${r.data.index}"><strong>${esc(topics.find(t=>t.id===r.data.topic)?.title||r.data.topic)}</strong>Question ${r.data.index+1} ↗</a></div>`).join('')||'<p class="caption">Tap “Save question” during practice to keep it here.</p>'}</aside></div>`;}
function newtonPage(){const t=topics.find(t=>t.id===route[1]),chat=current('chat','newton')?.messages||[];return title('MEET NEWTON','Let’s untangle that thought.','Ask for a hint, a simpler explanation, or help checking your working.')+`<div class="two-cols"><section class="panel"><div class="actions"><div class="newton-face" style="width:45px;height:45px;font-size:20px">⌐◉_◉</div><div><strong>Newton</strong><br><small id="newton-status">${api.session?'Checking tutor connection…':'Sign in to use Newton'}</small></div>${btn('clear-chat','Clear conversation','ghost','style="margin-left:auto"')}</div><div class="toolbar"><select id="newton-style" aria-label="Explanation style"><option value="simple">Keep it simple</option><option value="hint">Give me a hint</option><option value="exam">Exam-level working</option></select><select id="newton-mode" aria-label="Tutor subject"><option value="science">Physical Sciences</option><option value="coding">Full-stack coding</option></select></div>${t?`<span class="pill">Learning context: ${esc(t.title)}</span>`:''}<div class="chat-box" id="chat-box">${chat.length?chat.map(chatMessage).join(''):`<div class="chat-message"><strong>NEWTON</strong><p>Where shall we start? Tell me the part that feels confusing, or paste a question with all its given information.</p></div>`}</div><div class="quick-prompts">${['Why is acceleration not zero at the highest point?','Explain internal resistance simply.','How do I choose the titration mole ratio?'].map(q=>`<button data-action="prompt" data-prompt="${esc(q)}">${q}</button>`).join('')}</div><form id="chat-form" class="chat-form" style="margin-top:18px"><textarea name="message" id="chat-input" aria-label="Your question for Newton" placeholder="The bit I don’t quite get is…" maxlength="6000" required></textarea><button class="button" ${state.chatBusy?'disabled':''}>${state.chatBusy?'Thinking…':'Ask ↗'}</button></form><p class="caption" style="margin-top:15px">When AI is connected, answers can contain mistakes. Check important steps against your lesson or official memo. Don’t include personal or sensitive information.</p></section><aside><div class="panel lilac"><h3>Good questions are a superpower.</h3><ul class="check-list"><li>“Why did we choose this formula?”</li><li>“Here’s my working. Where did I go wrong?”</li><li>“Give me a hint without the answer.”</li><li>“Explain it using a everyday example.”</li></ul></div><div class="panel"><h3>Prefer a worked example?</h3><p class="caption">The structured practice bank is always available, even when the tutor model is not connected.</p><a class="button secondary" href="#learn/1">Open the learning library ↗</a></div></aside></div>`;}
function chatMessage(m){return`<article class="chat-message ${m.role==='user'?'user':''}"><strong>${m.role==='user'?'YOU':m.mode==='study-guide'?'NEWTON · STUDY GUIDE':'NEWTON · AI TUTOR'}</strong><p>${esc(m.text)}</p>${m.sources?.length?`<small>Related lessons: ${m.sources.map(s=>`<a class="link-button" href="#topic/${esc(s.id)}">${esc(s.title)}</a>`).join(' · ')}</small>`:''}</article>`;}
function loginNotice(text='Sign in to use this part of your studio.'){return`<div class="panel align-center"><div class="topic-icon" style="margin:0 auto 20px">↗</div><h2>Your own little space.</h2><p>${text}</p>${btn('auth','Log in / Sign up','')}</div>`;}
function educatorPage(){if(!api.session)return title('EDUCATOR STUDIO','Your classroom, your resources.','Upload once. Keep every learner’s next step within reach.')+loginNotice('Log in to your educator account to manage resources.');if(!state.educator)return title('EDUCATOR STUDIO','Let’s set up your studio.','Student accounts cannot upload or publish resources.')+`<div class="panel"><h2>Educator activation</h2><p>The owner’s one-time setup code activates educator access for the signed-in account. Keep that code private.</p><form id="claim-form"><label>Private setup code<input name="code" type="password" required autocomplete="off" maxlength="100"></label><button class="button">Activate educator access</button><p class="form-error" role="alert"></p></form></div>`;
return title('EDUCATOR STUDIO','A home for your teaching.','Add resources directly. Students see only the items you publish.')+`<div class="two-cols"><section><div class="panel"><h2>Add a resource</h2><form id="upload-form"><label>Resource title<input name="title" required maxlength="180" placeholder="e.g. Momentum — a step-by-step worksheet"></label><label>Description<textarea name="description" maxlength="6000" placeholder="What will learners take away from this?"></textarea></label><div class="inline-fields"><label>Paper<select name="paper" id="upload-paper"><option value="1">Paper 1 · Physics</option><option value="2">Paper 2 · Chemistry</option></select></label><label>Type<select name="kind"><option value="lesson">Lesson notes</option><option value="worksheet">Worksheet</option><option value="paper">Question paper</option><option value="memo">Memorandum</option><option value="video">Video link</option><option value="link">External resource</option></select></label></div><label>Section<select name="topic" id="upload-topic">${topics.filter(t=>t.paper===1).map(t=>`<option value="${t.id}">${esc(t.title)}</option>`).join('')}</select></label><div class="inline-fields"><label>Year, if applicable<input name="year" type="number" min="1990" max="2100" placeholder="2025"></label><label>Exam sitting<input name="sitting" maxlength="100" placeholder="November / May–June"></label></div><div class="inline-fields"><label>Language<select name="language"><option>English</option><option>Afrikaans</option><option>isiZulu</option><option>Other</option></select></label><label>Pair with a paper or memo<select name="paired_resource"><option value="">No pairing</option>${state.resources.filter(r=>['paper','memo'].includes(r.kind)).map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('')}</select></label></div><label>PDF, image or plain text · maximum 20 MB<input name="file" type="file" accept="application/pdf,image/png,image/jpeg,image/webp,text/plain"></label><label>Or an external HTTPS link<input name="external_url" type="url" placeholder="https://…"></label><div class="check-row"><input name="original" id="original" type="checkbox" checked><label for="original">Original material created by Simoné Govender</label></div><label>Original publisher / author, if external<input name="source_author" value="Simoné Govender" maxlength="150"></label><div class="check-row"><input name="published" id="published" type="checkbox"><label for="published">Publish for learners now (otherwise save as draft)</label></div><button class="button" style="margin-top:15px">Save resource</button><p class="form-error" role="alert"></p></form></div></section><aside><div class="panel"><h3>Connect Newton’s AI</h3><p class="caption">Add your Google Gemini API key. It is sent to the server and never returned to students. Provider usage may incur charges.</p><form id="model-form"><label>Model API key<input name="api_key" type="password" autocomplete="new-password" minlength="15" required></label><label>Model name<input name="model" value="gemini-3.8-flash" required pattern="gemini-[a-zA-Z0-9.\-]+"></label><button class="button secondary">Test & connect</button><p class="form-error" role="alert"></p></form></div><div class="panel peach"><h3>Keep your stamp on it.</h3><p class="caption">Original resources carry “Created by Simoné Govender”. Official papers keep their DBE attribution, with your curator credit.</p><a class="link-button" href="#resources">See the learner resource shelf ↗</a></div></aside></div><div class="section-heading"><h2>Your uploads</h2>${btn('refresh-resources','Refresh','secondary small')}</div><div class="three-cols">${resourceCards(true)}</div>`;}
function resourceCards(admin=false){const list=state.resources.filter(r=>admin?r.owner_id===api.session?.user.id:r.published);return list.map(r=>`<article class="panel resource-card"><div class="actions"><span class="pill">PAPER ${r.paper}</span><span class="pill">${esc(r.kind)}${admin?(r.published?' · PUBLISHED':' · DRAFT'):''}</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description)}</p><p class="caption">${r.original?CREDIT:`Source: ${esc(r.source_author)} · Curated by Simoné Govender`}</p><div class="actions">${btn('open-resource','Open ↗','secondary',`data-id="${r.id}"`)}${admin?`${btn('toggle-resource',r.published?'Unpublish':'Publish','ghost',`data-id="${r.id}"`)}${btn('edit-resource','Edit','ghost',`data-id="${r.id}"`)}${btn('delete-resource','Remove','ghost danger',`data-id="${r.id}"`)}`:''}</div></article>`).join('')||'<div class="empty">No resources here yet. The learning and past-paper libraries are already available.</div>';}
function resourcesPage(){return title('YOUR EDUCATOR’S SHELF','A little extra, from your teacher.','Published notes, worksheets and resources for your next study session.',`<a class="button secondary" href="#learn/1">Learning library</a>`)+`<div class="three-cols" id="resource-shelf">${resourceCards()}</div>`;}
function accountPage(){if(!api.session)return title('YOUR ACCOUNT','A place for your progress.','Sign in to carry your notes and study plan between devices.')+loginNotice();const name=state.profile?.display_name||'Learner';return title('YOUR ACCOUNT','Your space, your pace.','Your notes and progress belong to your account.',btn('logout','Log out','secondary'))+`<div class="two-cols"><div class="panel"><h2>Profile</h2><form id="profile-form"><label>Display name<input name="name" maxlength="80" value="${esc(name)}" required></label><p class="caption">${esc(api.session.user.email)}</p><button class="button">Save profile</button><p class="form-error" role="alert"></p></form><div class="actions" style="margin-top:24px">${btn('accessibility','Study preferences','secondary')}${btn('export-data','Export my data','ghost')}</div></div><div class="panel"><h2>Change password</h2><form id="password-form"><label>New password<input name="password" type="password" minlength="10" required autocomplete="new-password"></label><button class="button secondary">Change password</button><p class="form-error" role="alert"></p></form></div></div>`;}
function about(){return title('ABOUT QUANTUM JUMP','A little curiosity goes a long way.','A study space for Grade 12 Physical Sciences.')+`<div class="panel"><h2>Hi, I’m Simoné.</h2><p>Bachelor of Education · Full-stack web developer</p><p>I created Quantum Jump to give learners a place to slow down, ask questions and practise Physical Sciences one step at a time. Pick a topic, watch a lesson, then try the working for yourself. Small steps still count.</p><h3>Make it part of your study routine</h3><p>Each topic brings together notes, video lessons and 100 practice questions, including numerical variations. Use the worked steps to check your method, then practise with official papers and memos.</p><h3>A little help from Newton</h3><p>Ask for a hint, a simpler explanation or help checking a calculation. Newton’s study guide uses the topic notes; when the AI tutor is connected, it can also answer your questions. Answers can contain mistakes, so check important steps against your lesson or an official memo.</p><h3>Your information</h3><p>Guest notes stay on this device. When you sign in, your notes, progress, tasks and conversations are saved to your account. Educators can share teaching resources, but cannot read your private notes or conversations through the studio.</p><p>When you use Newton’s connected AI tutor, your question and recent conversation context are shared with the tutor service to prepare a response. Please leave out personal or sensitive information.</p><h3>Study comfortably</h3><p>Choose the text size, contrast, reading support and motion settings that work for you. Use the focus timer, take a break and come back when you’re ready. These settings are optional; you don’t need to share a diagnosis.</p><h3>Credit where it belongs</h3><p>Study resources: ${CREDIT}. Official papers and memos keep their issuing department’s credits. Video lessons belong to their credited YouTube educators. PhET simulations are from the University of Colorado Boulder.</p><ul class="check-list">${officialSources.map(s=>`<li><a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.title)} ↗</a><br><small>${esc(s.description)}</small></li>`).join('')}</ul><div class="actions"><a class="button secondary" href="#resources">Educator resources</a>${btn('export-data','Export saved data','ghost')}</div></div>`;}

async function render(){const id=++renderId;route=(location.hash.slice(1)||'home').split('/');const name=route[0];document.title=`${name==='home'?'Small steps. Big understanding.':({learn:'Learn & practise',videos:'Video lessons',topic:'Learning studio',practice:'Worked practice',papers:'Past papers',lab:'Experiment lab',toolkit:'Revision toolkit',planner:'Study plan',newton:'Newton',educator:'Educator studio',saved:'My notebook',resources:'Resources',account:'My account',about:'About Quantum Jump'}[name]||'Learning studio')} — Quantum Jump`;$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(['topic','practice'].includes(name)?'learn':name)));$('.sidebar').classList.remove('open');const views={home,learn,videos:videosPage,topic:topicPage,practice,papers:paperPage,lab,toolkit,planner,saved:savedPage,newton:newtonPage,educator:educatorPage,resources:resourcesPage,account:accountPage,about};main.innerHTML=(views[name]||home)();mountVideoLibraries();$('.mobile-menu').setAttribute('aria-expanded','false');$$('[data-nav]').forEach(a=>{if(a.classList.contains('active'))a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});$('.breadcrumb').innerHTML=`<a href="#home">Home</a>${name!=='home'?` / <a href="#learn/${topics.find(t=>t.id===route[1])?.paper||1}">Topics</a>`:''}`;window.scrollTo(0,0);if(id>1)main.focus({preventScroll:true});if(name==='lab')updateSim();if(name==='newton'&&api.session){try{const s=await api.newton({action:'status'});if(id!==renderId)return;state.newtonMode=s.mode;$('#newton-status').textContent=s.mode==='ai'?'AI tutor connected':'Study guide · AI model not yet connected';}catch(e){if(id===renderId)$('#newton-status').textContent=e.message;}}if(['educator','resources'].includes(name)){try{state.resources=await api.resources();if(id!==renderId)return;if(name==='resources')$('#resource-shelf').innerHTML=resourceCards();else if(state.educator)main.innerHTML=educatorPage();}catch(e){toast(e.message)}}}

function authDialog(mode='login'){const labels={login:['Welcome back.','Your next little leap is waiting.'],signup:['Make room for your next aha.','Create your free student account to save your progress.'],recover:['Let’s get you back in.','Request a password reset email.'],confirm:['Check your inbox.','Confirm your email before signing in.'],reset:['Choose a fresh password.','Use the recovery code from your email.']};const [heading,desc]=labels[mode];modal(`<div class="eyebrow">QUANTUM JUMP</div><h2>${heading}</h2><p class="caption">${desc}</p><div class="auth-tabs"><button data-action="auth-mode" data-mode="login" class="${mode==='login'?'active':''}">Log in</button><button data-action="auth-mode" data-mode="signup" class="${mode==='signup'?'active':''}">Sign up</button></div><form id="auth-form" data-mode="${mode}">${mode==='signup'?'<label>Your name<input name="name" required maxlength="80" autocomplete="name"></label>':''}<label>Email<input name="email" type="email" required autocomplete="email"></label>${!['recover','confirm'].includes(mode)?`<label>${mode==='reset'?'New password':'Password'}<input name="password" type="password" required minlength="${mode==='login'?1:10}" autocomplete="${mode==='login'?'current-password':'new-password'}"></label>`:''}${['confirm','reset'].includes(mode)?'<label>Email code<input name="token" required inputmode="numeric" autocomplete="one-time-code"></label>':''}<button class="button" style="width:100%">${{login:'Log in →',signup:'Create my account →',recover:'Send reset email',confirm:'Verify email',reset:'Set password'}[mode]}</button><p class="form-error" role="alert"></p></form><div class="actions">${btn('auth-mode','Forgot password?','ghost',`data-mode="recover"`)}${btn('auth-mode','Confirm email','ghost',`data-mode="confirm"`)}${btn('auth-mode','Use recovery code','ghost',`data-mode="reset"`)}</div><p class="caption" style="margin-top:15px">Guest notes stay on this device. Account notes are saved separately. <a href="#about" data-action="close">Privacy details ↗</a></p>`);}
function accessibility(){const p=state.preferences;modal(`<div class="eyebrow">MAKE YOURSELF COMFORTABLE</div><h2>There’s no one way to learn.</h2><p class="caption">Choose what helps today. You don’t need a label or diagnosis.</p><label>Text size<select id="pref-size"><option value="1" ${!p.size||p.size==1?'selected':''}>Standard</option><option value="1.15" ${p.size==1.15?'selected':''}>Larger</option><option value="1.3" ${p.size==1.3?'selected':''}>Extra large</option></select></label><label>Line spacing<select id="pref-spacing"><option value="1.65" ${!p.spacing||p.spacing==1.65?'selected':''}>Comfortable</option><option value="2" ${p.spacing==2?'selected':''}>Spacious</option><option value="2.3" ${p.spacing==2.3?'selected':''}>Extra spacious</option></select></label>${[['dark','Dark theme'],['contrast','Higher contrast'],['motion','Reduce motion'],['quiet','Sensory-quiet display'],['focus','Focus mode · fewer distractions'],['reading','Reading guide · follows your pointer'],['hideTimers','Hide timer numbers and countdowns']].map(([key,label])=>`<div class="check-row"><input type="checkbox" id="pref-${key}" data-pref="${key}" ${p[key]?'checked':''}><label for="pref-${key}">${label}</label></div>`).join('')}<div class="actions" style="margin-top:20px">${btn('save-preferences','Save preferences','')}${btn('reset-preferences','Reset preferences','secondary')}</div>`);}
function showError(form,e){const box=$('.form-error',form);if(box)box.textContent=e.message;else toast(e.message)}
async function handleSubmit(event){const form=event.target;if(!form.matches('form'))return;event.preventDefault();const data=Object.fromEntries(new FormData(form));const submit=$('button[type=submit],button:not([type])',form);if(submit)submit.disabled=true;const error=$('.form-error',form);if(error)error.textContent='';try{
switch(form.id){
case 'auth-form':{const mode=form.dataset.mode;if(mode==='login')await api.login(data.email,data.password);if(mode==='signup'){const r=await api.signup(data.email,data.password,data.name);if(!r.access_token){error.textContent='Check your inbox and confirm your email, then return here to log in. If you already have an account, use Log in.';return;}}if(mode==='recover'){await api.recover(data.email);error.className='form-success';error.textContent='If that account exists, a reset email has been requested. Follow its recovery link, or use the code if your email includes one.';return;}if(mode==='confirm')await api.confirm(data.email,data.token);if(mode==='reset')await api.recoveryCode(data.email,data.token,data.password);await hydrate();close();location.hash='home';render();toast('You’re signed in. Your account progress is ready.');break;}
case 'answer-form':{const e=activeExample;const text=String(data.answer).trim().replace(/,/g,'');const num=Number(text);if(!Number.isFinite(num)||!text)throw Error('Use a number, including scientific notation such as 2.5e-3.');const correct=Math.abs(num-e.number)<=Math.max(Math.abs(e.number)*.02,1e-40);await save('attempt',`${e.id}-${Date.now()}`,{topic:topics.find(t=>t.id===e.topic).title,topicId:e.topic,index:e.index,answer:text,correct});$('#answer-feedback').textContent=correct?'✓ That numerical value matches. Check that your units and reasoning match too.':'Not quite yet. Check the signs and units, then reveal one step.';break;}
case 'unit-form':{const [factor,unit]=data.conversion.split('|');const result=Number(data.value)*Number(factor);$('#unit-result').textContent=`${data.value} × ${factor} = ${Number(result.toPrecision(8))} ${unit}`;break;}
case 'task-form':await save('task',crypto.randomUUID(),{text:data.task.trim(),done:false});form.reset();$('#task-list').innerHTML=taskList();break;
case 'plan-form':await save('plan','settings',{...current('plan','settings'),exam:data.exam,intention:data.intention,focus:Number($('#focus-min').value),break:Number($('#break-min').value)});toast('Study plan saved.');render();break;
case 'profile-form':await api.profile(data.name,state.preferences);state.profile={display_name:data.name,preferences:state.preferences};accountUI();toast('Profile saved.');break;
case 'password-form':await api.password(data.password);form.reset();toast('Password changed.');break;
case 'claim-form':await api.newton({action:'claim',code:data.code});await hydrate();form.reset();render();toast('Your educator studio is ready.');break;
case 'model-form':await api.newton({action:'configure',provider:'gemini',api_key:data.api_key,model:data.model});form.reset();toast('Newton’s AI model is connected.');break;
case 'edit-resource-form':await api.editResource(form.dataset.id,{title:data.title,description:data.description});close();state.resources=await api.resources();render();toast('Resource updated.');break;
case 'upload-form':{let path=null;const file=form.elements.file.files[0];if(!file&&!data.external_url&&!data.description.trim())throw Error('Add a file, an HTTPS link or lesson text.');if(file){if(file.size>20971520)throw Error('Please choose a file smaller than 20 MB.');if(!['application/pdf','image/png','image/jpeg','image/webp','text/plain'].includes(file.type))throw Error('Use a PDF, PNG, JPEG, WebP or plain-text file.');toast('Uploading your resource…');path=await api.upload(file);}if(data.external_url&&!/^https:\/\//i.test(data.external_url))throw Error('External links must start with https://');try{await api.resource({title:data.title,description:data.description,paper:Number(data.paper),topic:data.topic,kind:data.kind,year:data.year?Number(data.year):null,sitting:data.sitting,language:data.language,source_author:data.original?'Simoné Govender':data.source_author,original:!!data.original,published:!!data.published,file_path:path,external_url:data.external_url||null,paired_resource:data.paired_resource||null});}catch(e){if(path)await api.deleteFile(path).catch(()=>{});throw e;}state.resources=await api.resources();render();toast(data.published?'Published for your learners.':'Draft saved to your studio.');break;}
case 'chat-form':{if(!api.session){authDialog();return}if(state.chatBusy)return;state.chatBusy=true;const msg=data.message.trim();const history=current('chat','newton')?.messages||[];const user={role:'user',text:msg};const style=$('#newton-style').value,mode=$('#newton-mode').value;$('#chat-box').innerHTML=[...history,user].map(chatMessage).join('')+'<p id="thinking" class="caption">Newton is working through that…</p>';$('#chat-box').scrollTop=$('#chat-box').scrollHeight;const result=await api.newton({action:'chat',message:msg,topic:route[1]||'',style,mode,history:history.map(m=>({role:m.role==='user'?'user':'model',text:m.text}))});const messages=[...history,user,{role:'model',text:result.answer,mode:result.mode,sources:result.sources}].slice(-8).map(m=>({...m,text:m.text.slice(0,9000)}));await save('chat','newton',{messages});$('#chat-box').innerHTML=messages.map(chatMessage).join('');$('#chat-box').scrollTop=$('#chat-box').scrollHeight;$('#chat-input').value='';$('#newton-status').textContent=result.mode==='ai'?'AI tutor connected':'Study guide · AI model not yet connected';break;}
}
}catch(e){showError(form,e);$('#thinking')?.remove();}finally{if(submit)submit.disabled=false;if(form.id==='chat-form')state.chatBusy=false;}}

async function handleAction(event){const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(target.tagName==='A'&&action==='close'){close();return;}event.preventDefault();try{switch(action){
case 'auth':if(api.session)location.hash='account';else authDialog();break;
case 'auth-mode':authDialog(target.dataset.mode);break;
case 'close':close();break;
case 'menu':$('.mobile-menu').setAttribute('aria-expanded',String($('.sidebar').classList.toggle('open')));break;
case 'topic-videos':$('.video-library')?.scrollIntoView({block:'start'});$('.video-library input')?.focus({preventScroll:true});break;
case 'theme':state.preferences.dark=!state.preferences.dark;applyPreferences();break;
case 'focus':state.preferences.focus=!state.preferences.focus;applyPreferences();toast(state.preferences.focus?'Focus mode is on. Tap Focus mode again to leave.':'Full studio restored.');break;
case 'accessibility':accessibility();break;
case 'save-preferences':if(api.session)await api.profile(state.profile?.display_name||'Learner',state.preferences);close();render();toast('Preferences saved.');break;
case 'reset-preferences':state.preferences={};applyPreferences();accessibility();break;
case 'logout':await api.logout();state.records=parse(localStorage.getItem('qj-guest-records'),[]);state.profile=null;state.educator=false;accountUI();location.hash='home';render();toast('You’re logged out.');break;
case 'save-note':await save('note',target.dataset.topic,{text:$('#topic-note').value});toast(api.session?'Note saved to your account.':'Note saved on this device.');break;
case 'complete':await save('progress',target.dataset.topic,{complete:!current('progress',target.dataset.topic)?.complete});render();break;
case 'next-step':revealed=Math.min(5,revealed+1);solution();break;
case 'all-steps':revealed=5;solution();break;
case 'print-example':revealed=5;solution();window.print();break;
case 'print':window.print();break;
case 'bookmark':{const e=activeExample;if(current('bookmark',e.id)){await remove('bookmark',e.id);target.textContent='♡ Save question';}else{await save('bookmark',e.id,{topic:e.topic,index:e.index});target.textContent='♥ Saved';}break;}
case 'self-attempt':{const e=activeExample,text=$('#written-answer').value.trim();if(!text)throw Error('Write a short explanation first.');await save('attempt',`${e.id}-${Date.now()}`,{topic:topics.find(t=>t.id===e.topic).title,topicId:e.topic,index:e.index,answer:text,correct:null});toast('Your response is saved. Reveal the solution to compare your reasoning.');break;}
case 'question':location.hash=`practice/${target.dataset.topic}/${target.dataset.index}`;break;
case 'random-example':location.hash=`practice/${target.dataset.topic}/${Math.floor(Math.random()*100)}`;break;
case 'speak':if(!('speechSynthesis'in window))throw Error('Speech playback is not supported in this browser.');speechSynthesis.cancel();{const speech=new SpeechSynthesisUtterance(target.dataset.text);speech.lang='en-ZA';speech.rate=.9;speechSynthesis.speak(speech);}break;
case 'stop-speech':window.speechSynthesis?.cancel();break;
case 'reset-sim':{const s=simulations.find(s=>s.id===route[1])||simulations[0];$('#sim-a').value=s.a[4];$('#sim-b').value=s.b[4];updateSim();break;}
case 'load-phet':$('#phet-embed').innerHTML='<iframe class="embed" title="PhET Circuit Construction Kit" loading="lazy" allowfullscreen src="https://phet.colorado.edu/sims/html/circuit-construction-kit-dc/latest/circuit-construction-kit-dc_all.html"></iframe>';target.disabled=true;break;
case 'tool-tab':{const tab=target.dataset.tab;$$('.tabs button').forEach(b=>b.classList.toggle('active',b===target));$('#tool-content').innerHTML=tab==='formulae'?formulae():tab==='flashcards'?flashcard():tab==='units'?unitTool():tab==='checklist'?checklist():`<div class="panel"><h2>Definitions, clearly.</h2><input type="search" id="glossary-search" aria-label="Search definitions" placeholder="Find a definition…"><div id="glossary-list">${glossary.map(([term,def])=>`<div class="detail-row"><strong>${term}</strong>${def}</div>`).join('')}</div>${credit()}</div>`;break;}
case 'flip-card':state.flashFlipped=!state.flashFlipped;$('#tool-content').innerHTML=flashcard();break;
case 'next-card':state.flash=(state.flash+1)%glossary.length;state.flashFlipped=false;$('#tool-content').innerHTML=flashcard();break;
case 'shuffle-card':state.flash=Math.floor(Math.random()*glossary.length);state.flashFlipped=false;$('#tool-content').innerHTML=flashcard();break;
case 'known-card':await save('progress','flash-'+state.flash,{complete:true});state.flash=(state.flash+1)%glossary.length;state.flashFlipped=false;$('#tool-content').innerHTML=flashcard();toast('One more idea made familiar.');break;
case 'delete-task':await remove('task',target.dataset.key);$('#task-list').innerHTML=taskList();break;
case 'timer-start':if(state.timer.run){state.timer.remaining=Math.max(0,Math.ceil((state.timer.end-Date.now())/1000));state.timer.run=false;}else{if(state.timer.remaining<=0)state.timer.remaining=Number($('#focus-min').value)*60;state.timer.end=Date.now()+state.timer.remaining*1000;state.timer.run=true;}target.textContent=state.timer.run?'Pause':'Start';break;
case 'timer-reset':state.timer.run=false;state.timer.kind='Focus';state.timer.remaining=Math.max(1,Math.min(180,Number($('#focus-min').value)||25))*60;$('#timer').textContent=timerText();$('#timer-start').textContent='Start';$('#timer-label').textContent='Focus session · no streaks to lose';break;
case 'timer-break':state.timer.run=false;state.timer.kind='Break';state.timer.remaining=Math.max(1,Math.min(60,Number($('#break-min').value)||5))*60;$('#timer').textContent=timerText();$('#timer-start').textContent='Start';$('#timer-label').textContent='Break session · take the space you need';break;
case 'export-data':download('Quantum_Jump_My_Study_Data.json',JSON.stringify({exported:new Date().toISOString(),profile:state.profile?.display_name||'Guest',preferences:state.preferences,records:state.records},null,2),'application/json');break;
case 'prompt':$('#chat-input').value=target.dataset.prompt;$('#chat-input').focus();break;
case 'clear-chat':await remove('chat','newton');render();toast('Conversation cleared from your saved notebook.');break;
case 'refresh-resources':state.resources=await api.resources();render();break;
case 'open-resource':{const r=state.resources.find(r=>r.id===target.dataset.id);if(r.external_url){const url=new URL(r.external_url);if(url.protocol!=='https:')throw Error('Only HTTPS resource links are supported.');window.open(url.href,'_blank','noopener');}else if(r.file_path){if(!api.session){authDialog();return;}const w=window.open('about:blank','_blank');try{const url=await api.fileUrl(r.file_path);if(w){w.opener=null;w.location=url}else location.href=url;}catch(e){w?.close();throw e;}}else modal(`<h2>${esc(r.title)}</h2><p style="white-space:pre-wrap">${esc(r.description)}</p><p class="credit">${r.original?CREDIT:esc(r.source_author)}</p>`);break;}
case 'toggle-resource':{const r=state.resources.find(r=>r.id===target.dataset.id);await api.editResource(r.id,{published:!r.published});state.resources=await api.resources();render();break;}
case 'edit-resource':{const r=state.resources.find(r=>r.id===target.dataset.id);modal(`<h2>Edit resource</h2><form id="edit-resource-form" data-id="${r.id}"><label>Title<input name="title" maxlength="180" required value="${esc(r.title)}"></label><label>Description<textarea name="description" maxlength="6000">${esc(r.description)}</textarea></label><button class="button">Save changes</button><p class="form-error" role="alert"></p></form>`);break;}
case 'delete-resource':{const r=state.resources.find(r=>r.id===target.dataset.id);modal(`<h2>Remove this resource?</h2><p>${esc(r.title)}</p><p class="caption">The upload and its listing will be removed.</p><div class="actions">${btn('confirm-delete-resource','Remove resource','accent',`data-id="${r.id}"`)}${btn('close','Keep it','secondary')}</div>`);break;}
case 'confirm-delete-resource':{const r=state.resources.find(r=>r.id===target.dataset.id);if(r.file_path)await api.deleteFile(r.file_path);await api.deleteResource(r.id);close();state.resources=await api.resources();render();toast('Resource removed.');break;}
}}catch(e){toast(e.message)}}

document.querySelector('.skip').addEventListener('click',e=>{e.preventDefault();main.focus();});
document.addEventListener('click',handleAction);document.addEventListener('submit',handleSubmit);
document.addEventListener('input',e=>{const t=e.target;if(t.id==='video-topic-search')$$('#video-topic-list .topic-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.id==='topic-search'){const q=t.value.toLowerCase(),p=Number(route[1])===2?2:1;$('#topic-list').innerHTML=topics.filter(x=>x.paper===p&&`${x.title} ${x.summary}`.toLowerCase().includes(q)).map(topicCard).join('')||'<div class="empty">No topic matched. Try another word.</div>';}if(t.id==='formula-search')$$('.formula-card').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.id==='glossary-search')$$('#glossary-list .detail-row').forEach(c=>c.hidden=!c.textContent.toLowerCase().includes(t.value.toLowerCase()));if(t.id==='sim-a'||t.id==='sim-b')updateSim();});
document.addEventListener('change',async e=>{const t=e.target;try{if(t.id==='topic-jump')location.hash=`${route[0]==='videos'?'videos':'topic'}/${t.value}`;if(t.dataset.pref){state.preferences[t.dataset.pref]=t.checked;applyPreferences();}if(t.id==='pref-size'||t.id==='pref-spacing'){state.preferences[t.id.slice(5)]=Number(t.value);applyPreferences();}if(t.id==='paper-year'||t.id==='paper-language')$('#paper-list').innerHTML=paperRows(Number(route[1])===2?2:1);if(t.id==='simulation-select')location.hash='lab/'+t.value;if(t.id==='upload-paper')$('#upload-topic').innerHTML=topics.filter(x=>x.paper===Number(t.value)).map(x=>`<option value="${x.id}">${esc(x.title)}</option>`).join('');if(t.dataset.checkTopic)await save('progress',t.dataset.checkTopic,{complete:t.checked});if(t.dataset.task){await save('task',t.dataset.task,{...current('task',t.dataset.task),done:t.checked});$('#task-list').innerHTML=taskList();}if(t.id==='focus-min'&&!state.timer.run&&state.timer.kind==='Focus'){state.timer.remaining=Math.max(1,Math.min(180,Number(t.value)||25))*60;$('#timer').textContent=timerText();}}catch(err){toast(err.message);}});
document.addEventListener('pointermove',e=>{if(state.preferences.reading)$('#reading-guide').style.top=`${e.clientY-18}px`});
setInterval(()=>{if(!state.timer.run)return;state.timer.remaining=Math.max(0,Math.ceil((state.timer.end-Date.now())/1000));if($('#timer'))$('#timer').textContent=timerText();if(state.timer.remaining===0){state.timer.run=false;if($('#timer-start'))$('#timer-start').textContent='Start';toast('Your session is complete. Take a comfortable break.');}},500);
window.addEventListener('hashchange',()=>{if(!location.hash.includes('access_token='))render();});
window.addEventListener('offline',()=>toast('You’re offline. Open lessons remain available; account changes need a connection.'));
applyPreferences();try{api.acceptRedirect()}catch{toast('That sign-in link could not be read. Please log in with your email and password.')}accountUI();render();hydrate().then(()=>{accountUI();if(['home','account','educator','saved','planner'].includes(route[0]))render()});


document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('.sidebar').classList.contains('open')){$('.sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false');$('.mobile-menu').focus()}});
document.addEventListener('click',e=>{if($('.sidebar').classList.contains('open')&&!e.target.closest('.sidebar,[data-action="menu"]')){$('.sidebar').classList.remove('open');$('.mobile-menu').setAttribute('aria-expanded','false')}});
